/bin/bash -c "python3 - <<'PY'
import re
from pathlib import Path
counts=[]
for p in (7,8,9):
    vals=[]
    for line in Path(f'tmp/pdfs/page-{p:02d}.txt').read_text().splitlines():
        pairs=re.findall(r'(\\d\\.\\d+)±(\\d\\.\\d+)',line)
        if not pairs:
            continue
        if p==9:
            if len(pairs)"'!=4:
                print('"'Unexpected row',p,line)
                continue
            vals.append((pairs[1][1],pairs[3][1]))
        elif len(pairs)%3==0:
            vals.extend((pairs[i][1],pairs[i+2][1]) for i in range(0,len(pairs),3))
        else:
            print('Unexpected row',p,line)
    counts.extend(vals)
    print('Page',p, 'language-condition rows:',len(vals),'identical displayed uncertainties:',sum(a==b for a,b in vals))
print('Total:',len(counts),'matching:',sum(a==b for a,b in counts))
PY"
